#!/usr/bin/env python3
"""Promptolog patch 3: Prompt Optimizer Pro (engine settings with provider adapters, 4 workflows, presets, scores, compression, library with folders).
Requires patches 1 and 2 (tokens-shell, obsidian-design-system) to be applied first.

Usage (repo root):
  python3 patch_2026-11-22-optimizer-pro.py --dry-run --diff   # validate and preview, writes nothing
  python3 patch_2026-11-22-optimizer-pro.py                    # apply
  python3 patch_2026-11-22-optimizer-pro.py --commit           # apply, then git add -A and one commit
Flags: --dry-run, --diff, --commit, --no-backup, --root PATH.
"""
import argparse, base64, difflib, hashlib, importlib.util, json, pathlib, shutil, subprocess, sys

sys.dont_write_bytecode = True  # importing docs_update must not leave __pycache__ for git add -A

PATCH_ID = "2026-11-22-optimizer-pro"
PATCH_DATE = "2026-11-22"
DATA = json.loads(base64.b64decode("").decode())
COMMIT_MSG = "feat: prompt optimizer pro (engine settings, four workflows, scores, compression, library with folders)"
DECISIONS = [
    "Prompt Optimizer Pro (2026-11-22): a standalone «Оптимизатор» screen (`#/optimizer`) and «Библиотека» screen (`#/library`) sit next to the Generator; the Generator, its skills, templates, history and favorites are unchanged. Server code: `engine.ts`, `optimizer.ts`, `optimizer-routes.ts`, shared contracts in `shared/src/optimizer.ts`, migration v2 (`optimizations`, `folders`).",
    "Engine settings (2026-11-22): provider (platform gateway by default, anthropic, openai, google, alibaba, moonshot, custom OpenAI-compatible), model, Custom Base URL, temperature, API key. Admin-only writes; the key is AES-256-GCM encrypted with `ENGINE_SECRET` and never returned to the browser; keys cannot be saved without the secret; Custom Base URL must be https and may not point to private or link-local addresses (`ENGINE_ALLOW_PRIVATE=1` only for local proxies).",
    "Structured output (2026-11-22): every engine call is fenced (user text inside `<user_input>` as data), parsed from JSON, validated by zod, and re-asked once with the validation error; scores are clamped to 1..10 and are the model's own estimate. The language-bridge sentence is appended server-side, never trusted to the model.",
    "Compression (2026-11-22): the compressed prompt is accepted only if it keeps every [Variable] and is shorter by the approximate token estimate (no tokenizer dependency); otherwise the original is kept and the UI says so. Compression keeps the prompt language.",
]
LIMITATIONS = [
    "Optimizer engine contracts (unverified, see `shared/src/optimizer.ts`): model ids other than Anthropic's come from the product spec and are not confirmed against provider docs; default base URLs and request shapes of OpenAI-compatible, Google, Alibaba and Moonshot providers follow public documentation and were tested only with mocked fetch; outbound egress from the Alaio platform to third-party providers is unverified; the platform gateway model list (`GET /models`) is not used for the optimizer catalog.",
    "Optimizer scope gaps: reverse engineering takes pasted text or .txt/.md/.csv/.json files up to 200 KB, not images or documents (needs a verified vision contract); token savings are estimates, not provider counts; the Generator and Optimizer do not share history yet.",
]
CHANGES = {
    "Added": ["Prompt Optimizer Pro: four workflows (one-click, clarifier with three questions, bracket-variable templates, reverse engineering), beginner goals and pro frameworks including ASD-STE100, output format and tone selectors, RU-EN-RU language bridge, initial and optimized score with changelog, prompt compression with approximate token savings.",
              "Library with automatic history, favorites, default and custom folders, tags and full-text search.",
              "Engine settings (provider, model, Custom Base URL, temperature, encrypted API key) with a connection test; `ENGINE_SECRET` and `ENGINE_ALLOW_PRIVATE` environment variables."],
    "Fixed": ["`npm run dev:server` now starts (`--experimental-transform-types`); parameter properties in `vibe.ts` are not supported by strip-only mode."],
}


def find_root(arg):
    p = pathlib.Path(arg or ".").resolve()
    for c in [p, *p.parents]:
        pj = c / "package.json"
        if pj.exists() and json.loads(pj.read_text(encoding="utf-8")).get("name") == "promptolog":
            return c
    sys.exit("error: run from the promptolog repo root (package.json name must be 'promptolog')")


def sha(b): return hashlib.sha256(b).hexdigest()


def replace_once(text, old, new, label):
    if new in text: return text
    n = text.count(old)
    if n != 1: raise ValueError(f"{label}: anchor found {n} times: {old[:70]!r}")
    return text.replace(old, new, 1)


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--dry-run", action="store_true"); ap.add_argument("--diff", action="store_true")
    ap.add_argument("--commit", action="store_true"); ap.add_argument("--no-backup", action="store_true"); ap.add_argument("--root")
    a = ap.parse_args()
    root = find_root(a.root)
    plan, errors, notes = {}, [], []  # rel -> bytes

    def cur(rel):
        p = root / rel
        return p.read_bytes() if p.exists() else None

    # --- phase 1: build and validate the whole plan in memory
    for op in DATA["ops"]:
        rel, new = op["path"], base64.b64decode(op["new"])
        old = cur(rel)
        if old is not None and sha(old) == sha(new): continue
        if op["base"] is None:
            if old is not None: errors.append(f"{rel}: exists and differs; refusing to overwrite a new file")
            else: plan[rel] = new
        elif old is None: errors.append(f"{rel}: missing")
        elif sha(old) != op["base"]: errors.append(f"{rel}: differs from the state after patches 1 and 2 (apply patches 1 and 2 first, or re-pack and ask for a rebuild)")
        else: plan[rel] = new

    for rel, old, new in DATA["edits"]:
        p = plan.get(rel); raw = (p if p is not None else cur(rel))
        if raw is None: errors.append(f"{rel}: missing"); continue
        try: txt = replace_once(raw.decode("utf-8"), old, new, rel)
        except ValueError as e: errors.append(str(e)); continue
        if txt.encode() != raw: plan[rel] = txt.encode()

    hold, cold = cur("HANDOFF.md"), cur("CHANGELOG.md")
    if hold is None or cold is None or cur("scripts/docs_update.py") is None: errors.append("HANDOFF.md, CHANGELOG.md or scripts/docs_update.py missing")
    elif PATCH_ID not in hold.decode("utf-8"):
        spec = importlib.util.spec_from_file_location("docs_update", root / "scripts/docs_update.py")
        du = importlib.util.module_from_spec(spec); spec.loader.exec_module(du)
        try:
            plan["HANDOFF.md"] = du.handoff_apply(hold.decode("utf-8"), PATCH_DATE, decisions=DECISIONS,
                limitations=LIMITATIONS, patches=[f"{PATCH_ID}: Prompt Optimizer Pro (engine settings, four workflows, scores, compression, library with folders)"]).encode()
            plan["CHANGELOG.md"] = du.changelog_add(cold.decode("utf-8"), CHANGES).encode()
        except SystemExit as e: errors.append(f"docs_update: {e}")

    pj = plan.get("package.json")
    if pj is not None:
        try: json.loads(pj)
        except Exception as e: errors.append(f"package.json would be invalid: {e}")

    if errors:
        print("VALIDATION FAILED, nothing written:"); [print("  -", e) for e in errors]; return 1
    for n in notes: print("note:", n)
    if not plan:
        print("Nothing to do"); archive(root, a); return commit_if(root, a)
    for rel in sorted(plan):
        print(f"{'create' if cur(rel) is None else 'update'}  {rel}")
        if a.diff and rel.endswith((".md", ".json", ".ts", ".tsx", ".css", ".html", ".mjs")):
            o = (cur(rel) or b"").decode("utf-8", "replace").splitlines(True); n = plan[rel].decode("utf-8", "replace").splitlines(True)
            sys.stdout.writelines(list(difflib.unified_diff(o, n, f"a/{rel}", f"b/{rel}"))[:400])
    if a.dry_run: print(f"\nDry run: {len(plan)} file(s) would change."); return 0

    # --- phase 2: backup and write
    bdir = root / ".patch-backup" / PATCH_ID
    for rel, data in plan.items():
        p = root / rel; old = cur(rel)
        if old is not None and not a.no_backup:
            (bdir / rel).parent.mkdir(parents=True, exist_ok=True); (bdir / rel).write_bytes(old)
        p.parent.mkdir(parents=True, exist_ok=True); p.write_bytes(data)
    print(f"\nApplied: {len(plan)} file(s). Backups: {bdir if not a.no_backup else 'disabled'}")
    archive(root, a)
    return commit_if(root, a)


def archive(root, a):
    if a.dry_run: return
    dst = root / "patches" / pathlib.Path(__file__).name
    if dst.resolve() != pathlib.Path(__file__).resolve() and not dst.exists():
        dst.parent.mkdir(exist_ok=True); shutil.copy2(__file__, dst); print(f"archived to patches/{dst.name}")


def commit_if(root, a):
    if not a.commit or a.dry_run: return 0
    subprocess.run(["git", "add", "-A"], cwd=root, check=True)
    r = subprocess.run(["git", "commit", "-m", COMMIT_MSG], cwd=root)
    return r.returncode


if __name__ == "__main__":
    sys.exit(main())
